import {t} from './i18n.js';
export const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={upload:'M12 16V4m-5 5 5-5 5 5M4 16v4h16v-4',reports:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',camera:'M3 7h4l2-3h6l2 3h4v14H3zM12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',check:'m5 12 4 4L19 6',arrow:'M5 12h14m-5-5 5 5-5 5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',audio:'M4 10h4l5-5v14l-5-5H4zM17 8c3 3 3 5 0 8'};
export function icon(name){return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${(paths[name]||paths.reports).split('~').map(d=>`<path d="${d}"/>`).join('')}</svg>`;}
export function button(id,key,primary=false,content=''){return `<button type="button" id="${id}" class="${primary?'primary':''}">${content}${h(t(key))}</button>`;}
export function options(values,current){return Object.entries(values).map(([value,label])=>`<option value="${h(value)}" ${value===current?'selected':''}>${h(label)}</option>`).join('');}
export function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.hidden=true;},7000);}
export function confirmAction(title,description,{typed=false}={}){return new Promise(resolve=>{
 const previous=document.activeElement,dialog=document.createElement('dialog');dialog.className='confirm-dialog';dialog.setAttribute('aria-labelledby','confirm-title');dialog.setAttribute('aria-describedby','confirm-description');dialog.innerHTML=`<h2 id="confirm-title">${h(title)}</h2><p id="confirm-description">${h(description)}</p>${typed?`<label for="confirm-text">${h(t('typeDelete'))}</label><input id="confirm-text" autocomplete="off">`:''}<div class="actions"><button id="cancel-confirm" autofocus>${h(t('cancel'))}</button><button id="accept-confirm" class="danger" ${typed?'disabled':''}>${h(t('confirm'))}</button></div>`;document.body.append(dialog);
 const finish=value=>{dialog.close();dialog.remove();previous?.isConnected&&previous.focus();resolve(value);};dialog.querySelector('#cancel-confirm').onclick=()=>finish(false);dialog.querySelector('#accept-confirm').onclick=()=>finish(true);dialog.addEventListener('cancel',event=>{event.preventDefault();finish(false);});if(typed)dialog.querySelector('input').oninput=event=>dialog.querySelector('#accept-confirm').disabled=event.target.value!=='DELETE';dialog.showModal();
 });}
export function validateForm(form){let first=null,key='error';for(const field of form.querySelectorAll('input,textarea,select')){const valid=field.checkValidity();field.setAttribute('aria-invalid',String(!valid));if(!valid&&!first){first=field;key=field.type==='email'?'emailInvalid':field.type==='password'&&field.id!=='backend-token'?'passwordInvalid':field.id==='question'?'questionRequired':'backendInvalid';}}if(first){first.focus();return t(key);}return '';}
